import assert from 'node:assert/strict';
import { test } from 'node:test';
import { taskLabel } from '../src/labels.ts';

test('completed task gets [x] prefix', () => {
  assert.equal(taskLabel('draft', true), '[x] draft');
});

test('incomplete task keeps [ ] prefix', () => {
  assert.equal(taskLabel('draft', false), '[ ] draft');
});

test('preserves empty name exactly', () => {
  assert.equal(taskLabel('', true), '[x] ');
  assert.equal(taskLabel('', false), '[ ] ');
});

test('preserves whitespace and special characters in name exactly', () => {
  assert.equal(taskLabel('  padded task  ', true), '[x]   padded task  ');
  assert.equal(taskLabel('task: #1 (urgent!)', true), '[x] task: #1 (urgent!)');
  assert.equal(taskLabel('line1\nline2', true), '[x] line1\nline2');
});
